import{_ as a,f as n,o as e,aq as o}from"./chunks/framework.BvNt3gUw.js";const u=JSON.parse('{"title":"Factories","description":"","frontmatter":{},"headers":[],"relativePath":"orm/factories.md","filePath":"en/orm/factories.md","lastUpdated":1789895472000}'),l={name:"orm/factories.md"};function p(r,s,t,c,i,y){return e(),n("div",null,s[0]||(s[0]=[o(`<h1 id="factories" tabindex="-1">Factories <a class="header-anchor" href="#factories" aria-label="Permalink to “Factories”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>When testing your application or seeding your database, it might be necessary to insert a few records into your database beforehand. Instead of manually inputting values for each column, Goravel allows you to define a set of default attributes for each of your models by creating model factories.</p><p>To see an example of how to write a factory, you can check out the <code>user_factory.go</code> file located in your application&#39;s <code>database/factories</code> directory.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">package factories</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">type UserFactory struct </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// Definition Define the model&#39;s default state.</span></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">f </span><span style="color:#68747D;">*</span><span style="color:#101820;">UserFactory</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Definition</span><span style="color:#68747D;">()</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">  return map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;Name&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;Goravel&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">  }</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>As you can see, in their most basic form, factories are structs that have a <code>Definition</code> method. The method returns the default set of attribute values that should be used when creating a model with the factory. To generate a range of random data, you can rely on <a href="https://github.com/brianvoe/gofakeit" target="_blank" rel="noreferrer">brianvoe/gofakeit</a>.</p><h2 id="generating-factories" tabindex="-1">Generating Factories <a class="header-anchor" href="#generating-factories" aria-label="Permalink to “Generating Factories”">​</a></h2><p>To create a factory, run the <code>make:factory</code> Artisan command:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">go</span><span style="color:#101820;"> run</span><span style="color:#101820;"> .</span><span style="color:#101820;"> artisan</span><span style="color:#101820;"> make:factory</span><span style="color:#101820;"> PostFactory</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The new factory <code>struct</code> will be placed in your <code>database/factories</code> directory.</p><h3 id="model-factory-discovery-conventions" tabindex="-1">Model &amp; Factory Discovery Conventions <a class="header-anchor" href="#model-factory-discovery-conventions" aria-label="Permalink to “Model &amp; Factory Discovery Conventions”">​</a></h3><p>After defining a factory, you can use the <code>Factory()</code> method in the model to bind the factory to the model:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">package models</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">  &quot;</span><span style="color:#101820;">github.com/goravel/framework/contracts/database/factory</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">  &quot;</span><span style="color:#101820;">github.com/goravel/framework/database/orm</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">  &quot;</span><span style="color:#101820;">goravel/database/factories</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">type User struct </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">  orm</span><span style="color:#68747D;">.</span><span style="color:#101820;">Model</span></span>
<span class="line"><span style="color:#101820;">  Name   </span><span style="color:#101820;">string</span></span>
<span class="line"><span style="color:#101820;">  Avatar </span><span style="color:#101820;">string</span></span>
<span class="line"><span style="color:#101820;">  orm</span><span style="color:#68747D;">.</span><span style="color:#101820;">SoftDeletes</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">u </span><span style="color:#68747D;">*</span><span style="color:#101820;">User</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Factory</span><span style="color:#68747D;">()</span><span style="color:#101820;"> factory</span><span style="color:#68747D;">.</span><span style="color:#101820;">Factory </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">  return </span><span style="color:#68747D;">&amp;</span><span style="color:#101820;">factories</span><span style="color:#68747D;">.</span><span style="color:#101820;">UserFactory</span><span style="color:#68747D;">{}</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h2 id="creating-models-using-factories" tabindex="-1">Creating Models Using Factories <a class="header-anchor" href="#creating-models-using-factories" aria-label="Permalink to “Creating Models Using Factories”">​</a></h2><h3 id="instantiating-models" tabindex="-1">Instantiating Models <a class="header-anchor" href="#instantiating-models" aria-label="Permalink to “Instantiating Models”">​</a></h3><p>We can use the <code>Make</code> method to create models without persisting them in the database:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">var user models</span><span style="color:#68747D;">.</span><span style="color:#101820;">User</span></span>
<span class="line"><span style="color:#101820;">err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Orm</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Factory</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Make</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">user</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>You may create a collection of many models using the <code>Count</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">var users </span><span style="color:#68747D;">[]</span><span style="color:#101820;">models</span><span style="color:#68747D;">.</span><span style="color:#101820;">User</span></span>
<span class="line"><span style="color:#101820;">err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Orm</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Factory</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Count</span><span style="color:#68747D;">(2).</span><span style="color:#0077B3;">Make</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">users</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If you would like to override some of the default values of your models, you may pass <code>map[string]any</code> to the <code>Make</code> method. Only the specified attributes will be replaced while the rest of the attributes remain set to their default values as specified by the factory:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">var user models</span><span style="color:#68747D;">.</span><span style="color:#101820;">User</span></span>
<span class="line"><span style="color:#101820;">err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Orm</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Factory</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Make</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">user</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;Avatar&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;avatar&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="persisting-models" tabindex="-1">Persisting Models <a class="header-anchor" href="#persisting-models" aria-label="Permalink to “Persisting Models”">​</a></h3><p>The <code>Create</code> method creates and saves model instances to the database using Orm&#39;s <code>Save</code> method.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">var user models</span><span style="color:#68747D;">.</span><span style="color:#101820;">User</span></span>
<span class="line"><span style="color:#101820;">err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Orm</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Factory</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Create</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">user</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">var users </span><span style="color:#68747D;">[]</span><span style="color:#101820;">models</span><span style="color:#68747D;">.</span><span style="color:#101820;">User</span></span>
<span class="line"><span style="color:#101820;">err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Orm</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Factory</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Count</span><span style="color:#68747D;">(2).</span><span style="color:#0077B3;">Create</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">users</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>You may override the factory&#39;s default model attributes by passing <code>map[string]any</code> of the attributes to the <code>Create</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">var user models</span><span style="color:#68747D;">.</span><span style="color:#101820;">User</span></span>
<span class="line"><span style="color:#101820;">err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Orm</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Factory</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Create</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">user</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">any</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;Avatar&quot;</span><span style="color:#68747D;">:</span><span style="color:#68747D;"> &quot;avatar&quot;</span><span style="color:#68747D;">,</span></span>
<span class="line"><span style="color:#68747D;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="ignore-model-event" tabindex="-1">Ignore Model Event <a class="header-anchor" href="#ignore-model-event" aria-label="Permalink to “Ignore Model Event”">​</a></h3><p>There may be <a href="./../orm/getting-started.html#events">model event</a> defined on the model, you can ignore those events with the <code>CreateQuietly</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">var user models</span><span style="color:#68747D;">.</span><span style="color:#101820;">User</span></span>
<span class="line"><span style="color:#101820;">err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Orm</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Factory</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">CreateQuietly</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">user</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,29)]))}const b=a(l,[["render",p]]);export{u as __pageData,b as default};
